<?php } ?><div class="caja-actions"><button type="submit" class="primary"><?=$action==='close'?'Confirmar recuento y cerrar':'Guardar movimiento'?></button><a class="caja-button" href="listado_caja.php?id_centro_caja=<?=$id?>">Cancelar</a></div></form></section>
